int get_sock_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc = NULL;

    if (!sock || !sockaddr || !sockaddr_len) {
        return -ENOTCONN;
    }

    if (peer) {
        vcc = sock->file->private_data;
    } else {
        vcc = sock->sk->sk_user_data;
    }

    if (!vcc || !vcc->vcc_sk || !vcc->vcc_sk->sk_bound_dev_if || vcc->vcc_sk->sk_state != TCP_ESTABLISHED) {
        return -ENOTCONN;
    }

    if (*sockaddr_len < sizeof(struct sockaddr)) {
        return -ENOTCONN;
    }

    memset(sockaddr, 0, *sockaddr_len);
    sockaddr->sa_family = AF_ATMPVC;

    struct sockaddr_atmpvc *atmpvc = (struct sockaddr_atmpvc *)sockaddr;
    atmpvc->sat_addr.addr_number = vcc->vcc_sk->sk_bound_dev_if;
    atmpvc->sat_addr.addr_vpi = vcc->vcc_sk->sk_vpi;
    atmpvc->sat_addr.addr_vci = vcc->vcc_sk->sk_vci;

    *sockaddr_len = sizeof(struct sockaddr_atmpvc);

    return 0;
}
